Add-Type -AssemblyName System.Drawing
$src = New-Object System.Drawing.Bitmap "<home>\source\repos\priv\monster-dev-testruns\2026-08-01-phase2.dist\monster-walk.png"
$H = 300; $W = 276; $band = 20   # bottom 20 rows = ground contact
$allMin = 9999; $allMax = -1
$rows = foreach ($f in 0..22) {
  $min = 9999; $max = -1
  for ($y = $H - $band; $y -lt $H; $y++) {
    for ($x = 0; $x -lt $W; $x++) {
      if ($src.GetPixel($f*$W + $x, $y).A -gt 40) {
        if ($x -lt $min) { $min = $x }; if ($x -gt $max) { $max = $x }
      }
    }
  }
  if ($max -ge 0) {
    if ($min -lt $allMin) { $allMin = $min }; if ($max -gt $allMax) { $allMax = $max }
    [pscustomobject]@{ Frame=$f; MinX=$min; MaxX=$max; Center=[math]::Round(($min+$max)/2) }
  } else { [pscustomobject]@{ Frame=$f; MinX='-'; MaxX='-'; Center='-' } }
}
$rows | Format-Table -AutoSize
"contact span across all frames: $allMin .. $allMax  (of $W)"
"as percent: $([math]::Round(100*$allMin/$W,1))% .. $([math]::Round(100*$allMax/$W,1))%"
"width: $([math]::Round(100*($allMax-$allMin)/$W,1))%   left offset: $([math]::Round(100*$allMin/$W,1))%"
$src.Dispose()

