// Throwaway CDP harness — lives outside the client project, deleted after the run.
import { writeFileSync } from 'node:fs';

const OUT = process.env.TEMP + '\\monster-check';
const PAGE = 'file:///<home>/source/repos/priv/monster-dev-testruns/2026-08-01-phase2/index.html';

const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find((t) => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));

let id = 0;
const pending = new Map();
const events = [];
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
  } else if (msg.method) events.push(msg);
};
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const n = ++id;
    pending.set(n, { resolve, reject });
    ws.send(JSON.stringify({ id: n, method, params }));
  });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const evalJs = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.text + ' :: ' + expr);
  return r.result.value;
};
const shot = async (name) => {
  const { data } = await send('Page.captureScreenshot', { format: 'png' });
  writeFileSync(`${OUT}\\${name}.png`, Buffer.from(data, 'base64'));
};
const altA = () =>
  send('Input.dispatchKeyEvent', {
    type: 'keyDown', modifiers: 1, code: 'KeyA', key: 'a',
    windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65,
  });

await send('Page.enable');
await send('Runtime.enable');
