/* Walking monster easter egg (Alt+A) — see script.js.
   Sprite sheet assets/monster-walk.png is 23 frames of 276 × 300 px, one full
   gait cycle at 24 fps. The vertical bob is painted into the frames, so there is
   deliberately no bounce animation here — adding one gives the monster a limp. */
:root {
  --monster-frame-w: 184px;                             /* display width of one frame */
  --monster-frame-h: 200px;                             /* 300/276 × 184 keeps the aspect ratio */
  --monster-sheet-w: calc(var(--monster-frame-w) * 23); /* must stay in step with steps(23) */
  --monster-cycle: 0.96s;                               /* 23 frames at 24 fps = original tempo */
  --monster-stride: 130px;                              /* ground covered per cycle — the speed knob:
                                                           larger is faster, until the feet skate */
  --monster-crossing: 16s;                              /* fallback; script.js derives the real one */
}

/* The wrapper carries the travel across the window … */
.monster {
  position: fixed;
  left: 0;
  bottom: 0;
  width: var(--monster-frame-w);
  height: var(--monster-frame-h);
  pointer-events: none;
  z-index: 10;
  animation: monster-crossing var(--monster-crossing) linear forwards;
}

/* … this layer only decides which way it faces. The artwork faces left, so walking
   left → right means mirroring it. Sprite and shadow sit inside together on purpose:
   flipping them separately is how a shadow ends up under the wrong foot. */
.monster-facing {
  position: absolute;
  inset: 0;
  transform: scaleX(-1);
}

/* … and the sprite only flips through the frames. */
.monster-sprite {
  position: absolute;
  inset: 0;
  background: url("assets/monster-walk.png") no-repeat;
  background-size: var(--monster-sheet-w) var(--monster-frame-h);
  animation: monster-gait var(--monster-cycle) steps(23) infinite;
}

/* Measured off the sheet: the feet touch the ground between 15% and 76% of the
   frame width across the cycle, centred on 46%. */
.monster-shadow {
  position: absolute;
  bottom: 0;
  left: 23%;
  width: 45%;
  height: 11px;
  background: rgba(60, 80, 60, 0.22);
  border-radius: 50%;
  filter: blur(3px);
}

/* Steps through all 23 frames of the sheet */
@keyframes monster-gait {
  from { background-position: 0 0; }
  to   { background-position: calc(-1 * var(--monster-sheet-w)) 0; }
}

/* Walks once from fully off the left edge to fully off the right edge */
@keyframes monster-crossing {
  from { transform: translateX(calc(-1 * var(--monster-frame-w))); }
  to   { transform: translateX(100vw); }
}

/* Someone who asked for less motion still gets the monster — it just stands there. */
@media (prefers-reduced-motion: reduce) {
  .monster {
    animation: none;
    transform: translateX(40vw);
  }

  .monster-sprite {
    animation: none;
  }
}

